  JOIN ${table_prefix}term_taxonomy tt ON tt."term_id" = t."term_id"
  WHERE t."slug" = 'uncategorized' AND tt."taxonomy" = 'product_cat'
  HAVING MIN(t."term_id") IS NOT NULL
ON CONFLICT DO NOTHING;

